const breathe = 1 + 0.06 * Math.sin(t * 2.5);
// draw hybrid orbital lobes / bonds in correct geometry (2D projection)
for (let i = 0; i < d.n; i++) {
  const a = d.dirs[i] * Math.PI / 180;
  const ex = cx + Math.cos(a) * R * breathe;
  const ey = cy - Math.sin(a) * R * breathe;
  H.line(cx, cy, ex, ey, { color: H.colors.accent2, width: 4 });
  H.circle(ex, ey, 16, { fill: H.colors.violet, stroke: H.colors.ink, width: 1.5 });
}
// sweeping angle probe dot tracing the characteristic bond angle
